package com.nyayaconnect.appointment;
import com.nyayaconnect.auth.SpringAccess;import com.nyayaconnect.common.*;import com.nyayaconnect.security.AuthenticationFilter;import com.nyayaconnect.security.SessionUser;import jakarta.servlet.http.*;import java.io.IOException;import java.time.LocalDateTime;import java.util.*;
public class AppointmentServlet extends HttpServlet {private AppointmentService service;public void init(){service=SpringAccess.bean(getServletContext(),AppointmentService.class);}
 protected void doPost(HttpServletRequest req,HttpServletResponse res)throws IOException{try{SessionUser u=(SessionUser)req.getSession(false).getAttribute(AuthenticationFilter.SESSION_KEY);Map<?,?> b=Json.MAPPER.readValue(req.getInputStream(),Map.class);UUID lawyer=UUID.fromString(get(b,"lawyerId"));LocalDateTime start=LocalDateTime.parse(get(b,"startsAt"));LocalDateTime end=LocalDateTime.parse(get(b,"endsAt"));UUID id=service.book(u,lawyer,start,end,get(b,"title","Legal consultation"),get(b,"category","General legal consultation"),get(b,"notes"),req.getRemoteAddr(),String.valueOf(req.getAttribute("X-Correlation-Id")));Api.json(res,201,Map.of("id",id,"status","PENDING"));}catch(SecurityException e){Api.error(res,403,"FORBIDDEN",e.getMessage());}catch(IllegalArgumentException|IllegalStateException e){Api.error(res,409,"APPOINTMENT_REJECTED",e.getMessage());}catch(Exception e){Api.error(res,500,"APPOINTMENT_FAILED","Appointment could not be created.");}}
 private static String get(Map<?,?>m,String k){return get(m,k,"");} private static String get(Map<?,?>m,String k,String d){Object v=m.get(k);return v==null?d:String.valueOf(v);}}
